"""Module for internal instrumentation - telemetry for telemetry."""
import logging
import traceback

from importlib.metadata import version, PackageNotFoundError
from functools import cache

from taf.ul.telemetry import settings
from taf.ul.telemetry.utils import set_telemetry_host, send_email_import_error, setup_exporters

logger = logging.getLogger(__name__)


@cache
def get_telemetry_instruments():
    try:
        from opentelemetry.sdk._logs import LoggerProvider, LoggingHandler
        from opentelemetry.sdk._logs.export import BatchLogRecordProcessor
        from opentelemetry.sdk.metrics import MeterProvider
        from opentelemetry.sdk.metrics.export import PeriodicExportingMetricReader
        from opentelemetry.sdk.resources import (
            SERVICE_NAME,
            SERVICE_VERSION,
            Resource,
            get_aggregated_resources,
        )
        from opentelemetry.sdk.trace import TracerProvider
        from opentelemetry.sdk.trace.export import BatchSpanProcessor
        from taf.ul.telemetry.resources import HostResourceDetector
        setup_exporters(create=False)
    except Exception:
        logger.debug("Could not import opentelemetry, skipping telemetry setup.")
        send_email_import_error(traceback.format_exc())
        from unittest.mock import MagicMock
        return MagicMock(), MagicMock()

    try:
        package_version = version("taf.ul.telemetry")
    except PackageNotFoundError:
        package_version = "0.0.0"

    # perform service discovery
    set_telemetry_host()

    # resource setup
    _base_resource = Resource.create({SERVICE_NAME: "taf.ul.telemetry", SERVICE_VERSION: package_version})
    _telemetry_resource = get_aggregated_resources([HostResourceDetector()], _base_resource)

    # logs setup
    _log_provider = LoggerProvider(_telemetry_resource)
    _handler = LoggingHandler(
        level=logging.getLevelName(logging.WARNING),
        logger_provider=_log_provider,
    )
    logging.getLogger("taf.ul.telemetry").addHandler(_handler)
    logging.getLogger("opentelemetry").addHandler(_handler)

    # trace setup
    _trace_provider = TracerProvider(resource=_telemetry_resource)

    tracer = _trace_provider.get_tracer("taf.ul.telemetry")
    _metrics_readers = []
    if not settings._NOOP:
        # exporters setup
        _metric_exporter, _trace_exporter, _log_exporter = setup_exporters()
        _log_provider.add_log_record_processor(BatchLogRecordProcessor(_log_exporter))
        _trace_provider.add_span_processor(BatchSpanProcessor(_trace_exporter))

        _metrics_readers.append(
            PeriodicExportingMetricReader(_metric_exporter, export_interval_millis=settings._INTERVAL_MS)
        )

    # metrics setup
    _metric_provider = MeterProvider(
        _metrics_readers,
        _telemetry_resource,
    )
    meter = _metric_provider.get_meter("taf.ul.telemetry")

    return tracer, meter
